export default function makeController() {
  const dt = 0.01;
  const g = 9.81;
  const mNom = 0.725;
  const accGain = 15.5 / mNom;
  const dragGain = 0.42 / mNom;
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

  let initialized = false;
  let vel = { x: 0, y: 0, z: 0 };
  let acc = { x: 0, y: 0, z: 0 };
  let fastD = { x: 0, y: 0, z: 0 };
  let slowD = { x: 0, y: 0, z: 0 };
  let posInt = { x: 0, y: 0, z: 0 };
  let yawInt = 0;
  let motorThrust = 0.45;
  let lastThrust = 0.45;

  let ref = { x: 0, y: 0, z: 0 };
  let targetIndex = -1;
  let phase = 'align';
  let settle = 0;
  let activeGate = null;
  let lockSteps = 0;
  let padY = 0.85;

  return {
    step(obs) {
      const p = obs.pos;
      const a = obs.att;
      const r = obs.rates;

      if (!initialized) {
        initialized = true;
        vel = { x: obs.vel.x, y: obs.vel.y, z: obs.vel.z };
        ref = { x: p.x, y: Math.max(0.35, p.y), z: p.z };
        if (obs.nextGate) {
          activeGate = { x: obs.nextGate.centre.x, y: obs.nextGate.centre.y, z: obs.nextGate.centre.z };
          targetIndex = obs.gateIndex;
        }
      }

      // 1. Filter velocity
      const prevVel = { x: vel.x, y: vel.y, z: vel.z };
      const alphaV = 0.35;
      vel.x += alphaV * (obs.vel.x - vel.x);
      vel.y += alphaV * (obs.vel.y - vel.y);
      vel.z += alphaV * (obs.vel.z - vel.z);

      const measAx = (vel.x - prevVel.x) / dt;
      const measAy = (vel.y - prevVel.y) / dt;
      const measAz = (vel.z - prevVel.z) / dt;

      acc.x += 0.25 * (measAx - acc.x);
      acc.y += 0.25 * (measAy - acc.y);
      acc.z += 0.25 * (measAz - acc.z);

      // 2. Fast/slow accel disturbance observer
      motorThrust += (1 - Math.exp(-dt / 0.04)) * (lastThrust - motorThrust);
      const bodyX = Math.sin(a.pitch) * Math.cos(a.roll);
      const bodyZ = -Math.sin(a.roll);
      const cy = Math.cos(a.yaw);
      const sy = Math.sin(a.yaw);
      const dirX = cy * bodyX + sy * bodyZ;
      const dirY = Math.cos(a.pitch) * Math.cos(a.roll);
      const dirZ = -sy * bodyX + cy * bodyZ;

      const expAx = accGain * motorThrust * dirX - dragGain * vel.x;
      const expAy = accGain * motorThrust * dirY - dragGain * vel.y - g;
      const expAz = accGain * motorThrust * dirZ - dragGain * vel.z;

      const airborne = p.y > 0.095 && p.y < 2.88 && Math.abs(p.x) < 2.78 && Math.abs(p.z) < 2.78;
      if (airborne) {
        const rawDx = clamp(measAx - expAx, -8, 8);
        const rawDy = clamp(measAy - expAy, -6, 6);
        const rawDz = clamp(measAz - expAz, -8, 8);

        fastD.x += 0.20 * (rawDx - fastD.x);
        fastD.y += 0.20 * (rawDy - fastD.y);
        fastD.z += 0.20 * (rawDz - fastD.z);

        slowD.x += 0.025 * (rawDx - slowD.x);
        slowD.y += 0.025 * (rawDy - slowD.y);
        slowD.z += 0.025 * (rawDz - slowD.z);
      } else {
        fastD.x += 0.08 * (slowD.x - fastD.x);
        fastD.y += 0.08 * (slowD.y - fastD.y);
        fastD.z += 0.08 * (slowD.z - fastD.z);
      }

      // 5. Gate exit lock & navigation state machine
      if (targetIndex < 3 && obs.gateIndex !== targetIndex && phase !== 'exit') {
        phase = 'exit';
        lockSteps = 0;
        posInt.x = 0;
      }

      if (phase === 'exit') {
        lockSteps++;
        if (p.x >= activeGate.x + 0.18 || (lockSteps > 28 && p.x >= activeGate.x + 0.06)) {
          targetIndex = obs.gateIndex;
          posInt = { x: 0, y: 0, z: 0 };
          settle = 0;
          if (obs.gateIndex < 3) {
            activeGate = { x: obs.nextGate.centre.x, y: obs.nextGate.centre.y, z: obs.nextGate.centre.z };
            phase = 'align';
          } else {
            phase = 'pad_align';
            padY = clamp(p.y, 0.70, 1.00);
          }
        }
      }

      const alignDist = 0.42;
      let target;

      if (phase === 'exit') {
        target = { x: activeGate.x + 0.28, y: activeGate.y, z: activeGate.z };
      } else if (targetIndex < 3) {
        const gate = activeGate;
        if (phase === 'align') {
          target = { x: gate.x - alignDist, y: gate.y, z: gate.z };
          const ex = Math.abs(target.x - p.x);
          const ey = Math.abs(gate.y - p.y);
          const ez = Math.abs(gate.z - p.z);
          const spd = Math.hypot(vel.x, vel.y, vel.z);
          const predY = p.y + vel.y * 0.22 + 0.5 * acc.y * 0.14 * 0.14;
          const predZ = p.z + vel.z * 0.22 + 0.5 * acc.z * 0.14 * 0.14;
          const gustOk = Math.abs(fastD.z - slowD.z) < 1.3 && Math.abs(fastD.y - slowD.y) < 1.3;
          if (
            ex < 0.11 &&
            ey < 0.085 &&
            ez < 0.060 &&
            spd < 0.30 &&
            Math.abs(vel.z) < 0.15 &&
            Math.abs(predY - gate.y) < 0.11 &&
            Math.abs(predZ - gate.z) < 0.075 &&
            gustOk
          ) {
            settle++;
          } else {
            settle = Math.max(0, settle - 1);
          }
          if (settle >= 10) {
            phase = 'cross';
            posInt.x = 0;
          }
        }

        if (phase === 'cross') {
          target = { x: gate.x + 0.30, y: gate.y, z: gate.z };
          // 6. Predictive cross abort
          const dx = gate.x - p.x;
          if (dx > 0.02) {
            const vxEff = Math.max(vel.x, 0.30);
            const tau = clamp(dx / vxEff, 0.04, 0.32);
            const tauA = Math.min(tau, 0.16);
            const predY = p.y + vel.y * tau + 0.5 * acc.y * tauA * tauA;
            const predZ = p.z + vel.z * tau + 0.5 * acc.z * tauA * tauA;
            const curY = Math.abs(p.y - gate.y);
            const curZ = Math.abs(p.z - gate.z);
            if (
              curY > 0.155 ||
              curZ > 0.085 ||
              Math.abs(predY - gate.y) > 0.165 ||
              Math.abs(predZ - gate.z) > 0.092
            ) {
              phase = 'align';
              settle = 0;
              posInt.x = 0;
              target = { x: gate.x - alignDist, y: gate.y, z: gate.z };
              ref.x = Math.min(ref.x, target.x - 0.08);
            }
          }
        }
      } else {
        // 7. Ramp pad descent
        const pad = obs.pad.centre;
        const hErr = Math.hypot(pad.x - p.x, pad.z - p.z);
        const hSpd = Math.hypot(vel.x, vel.z);
        if (phase === 'pad_align') {
          if (hErr < 0.14 && hSpd < 0.28 && Math.abs(p.y - padY) < 0.18) {
            phase = 'descend';
          }
        }
        if (phase === 'descend') {
          if (hErr < 0.115 && hSpd < 0.32) {
            const rate = p.y > 0.26 ? 0.46 : 0.22;
            padY = Math.max(0.015, padY - rate * dt);
          } else if (hErr > 0.145 && p.y > 0.12) {
            padY = Math.min(0.45, Math.max(padY, p.y));
          }
        }
        target = { x: pad.x, y: padY, z: pad.z };
      }

      // 4. Smooth ref filter
      const rdx = target.x - ref.x;
      const rdy = target.y - ref.y;
      const rdz = target.z - ref.z;
      const rDist = Math.hypot(rdx, rdy, rdz);
      const maxSpeed = phase === 'cross' ? 1.25 : 2.10;
      const alphaRef = phase === 'cross' ? 0.12 : 0.10;
      const stepScale = rDist > 1e-6 ? Math.min(alphaRef, (maxSpeed * dt) / rDist) : alphaRef;
      const refVx = (rdx * stepScale) / dt;
      const refVy = (rdy * stepScale) / dt;
      const refVz = (rdz * stepScale) / dt;
      ref.x += rdx * stepScale;
      ref.y += rdy * stepScale;
      ref.z += rdz * stepScale;

      // 3. Yaw + local pos integrals
      if (airborne) {
        yawInt = clamp(yawInt + a.yaw * dt, -0.6, 0.6);
        if (Math.abs(target.x - p.x) < 0.35 && phase !== 'cross') {
          posInt.x = clamp(posInt.x + (target.x - p.x) * dt, -0.45, 0.45);
        } else {
          posInt.x *= 0.96;
        }
        if (Math.abs(target.y - p.y) < 0.35) {
          posInt.y = clamp(posInt.y + (target.y - p.y) * dt, -0.45, 0.45);
        } else {
          posInt.y *= 0.96;
        }
        if (Math.abs(target.z - p.z) < 0.35) {
          posInt.z = clamp(posInt.z + (target.z - p.z) * dt, -0.45, 0.45);
        } else {
          posInt.z *= 0.96;
        }
      }

      const distX = slowD.x + 0.85 * (fastD.x - slowD.x);
      const distY = slowD.y + 0.55 * (fastD.y - slowD.y);
      const distZ = slowD.z + 0.85 * (fastD.z - slowD.z);

      const ex = ref.x - p.x;
      const ey = ref.y - p.y;
      const ez = ref.z - p.z;

      const kpx = 5.2, kdx = 3.8, kix = 1.8;
      const kpz = 5.6, kdz = 4.0, kiz = 2.0;
      const kpy = 6.0, kdy = 4.0, kiy = 2.2;

      const axCmd = clamp(
        kpx * ex + kdx * (0.35 * refVx - vel.x) + kix * posInt.x + dragGain * vel.x - distX,
        -4.5,
        4.5
      );
      const azCmd = clamp(
        kpz * ez + kdz * (0.35 * refVz - vel.z) + kiz * posInt.z + dragGain * vel.z - distZ,
        -4.5,
        4.5
      );
      const ayCmd = clamp(
        kpy * ey + kdy * (0.35 * refVy - vel.y) + kiy * posInt.y + dragGain * vel.y - distY,
        -4.5,
        5.5
      );

      const ayTotal = Math.max(2.0, g + ayCmd);
      const bodyAx = cy * axCmd - sy * azCmd;
      const bodyAz = sy * axCmd + cy * azCmd;

      let maxTilt = 0.48;
      if (targetIndex === 3 && p.y < 0.18) {
        maxTilt = p.y < 0.105 ? 0.13 : 0.16;
      }

      const pitch = clamp(Math.atan2(bodyAx, ayTotal), -maxTilt, maxTilt);
      const roll = clamp(Math.atan2(-bodyAz, Math.hypot(ayTotal, bodyAx)), -maxTilt, maxTilt);

      const tiltCos = Math.max(0.65, Math.cos(a.roll) * Math.cos(a.pitch));
      let thrust = clamp(ayTotal / (accGain * tiltCos), 0, 1);

      if (targetIndex === 3 && phase === 'descend' && p.y <= 0.088 && Math.hypot(obs.pad.centre.x - p.x, obs.pad.centre.z - p.z) < 0.125) {
        thrust = Math.min(thrust, 0.18);
      }

      lastThrust = thrust;
      const yawRate = clamp(-3.2 * a.yaw - 2.0 * yawInt - 0.25 * r.yaw, -2, 2);

      return { thrust, roll, pitch, yawRate };
    },
  };
}

